def basis(t, e, tau, mode):
    from scipy.signal import lfilter
    dt = t[1] - t[0]
    r = np.exp(-dt / tau)
    w = -np.expm1(-dt / tau) * tau / dt
    de = np.diff(e, prepend=e[0])
    grad = np.gradient(e, t)
    if mode == 'linear':
        return np.array([lfilter([b], [1, -a], de) for (a, b) in zip(r, w)]).T
    if mode == 'grad_right':
        rate = np.r_[0.0, grad[1:]]
    if mode == 'grad_left':
        rate = np.r_[0.0, grad[:-1]]
    if mode == 'grad_trap':
        return np.array([lfilter([1], [1, -a], np.r_[0.0, (grad[1:] + a * grad[:-1]) * dt / 2]) for a in r]).T
    return np.array([lfilter([b * dt], [1, -a], rate) for (a, b) in zip(r, w)]).T
